DROP TABLE IF EXISTS `party_addresses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `party_addresses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `party_id` int NOT NULL,
  `kind` enum('FISCAL','MAILING','OTHER') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FISCAL',
  `label` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `street` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `zip` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `same_as_fiscal` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `party_addresses_party_id_idx` (`party_id`),
  CONSTRAINT `party_addresses_party_id_fkey` FOREIGN KEY (`party_id`) REFERENCES `parties` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
